        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, lower(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, lower(e.headers), e.read()
    except (OSError, http.client.HTTPException) as e:
        return None, {}, repr(e).encode()


def pause_for_rate_limit(path, headers, body):
    raw = headers.get("retry-after")
    if raw is None:
        raise SystemExit(f"429 on {path} with no Retry-After header; body={body[:300]!r}")
    try:
        wait = max(0.0, float(raw))
    except ValueError:
        when = parsedate_to_datetime(raw)
        wait = max(0.0, (when - datetime.now(timezone.utc)).total_seconds())
    log(f"429 on {path}: Retry-After={raw}, waiting {wait:g}s")
    time.sleep(wait + 0.5)


def get_token():
    global token
    failures = 0
    while True:
        status, headers, body = send("POST", "/token")
        if status == 429:
            pause_for_rate_limit("/token", headers, body)
            continue
        try:
            if status == 200:
                token = json.loads(body)["token"]
                log("token acquired")
                return
        except (ValueError, KeyError):
            pass
        failures += 1
        if failures > MAX_FAILURES:
            raise SystemExit(f"POST /token keeps failing; last status {status}")
        log(f"POST /token: HTTP {status}; retry {failures}")
        time.sleep(min(30, failures))


def call(path, valid):
    """GET an authenticated path until it returns a valid 200, which comes back as (200, data).

    A 404 comes back as (404, None) once it has repeated three times (the customer endpoint uses it
    for unknown ids). 401/403 get a fresh token before the retry, 429 waits out Retry-After, and any
    other failure backs off and retries the same request.
    """
    global token
    failures = 0
    not_found = 0
    while True:
        if token is None:
            get_token()
        status, headers, body = send("GET", path, token)
        if status == 429:
            pause_for_rate_limit(path, headers, body)
            continue
        if status == 200:
            try:
                data = json.loads(body)
            except ValueError:
                data = None
            if data is not None and valid(data):
                return 200, data
            reason = f"200 with a body that failed validation: {body[:200]!r}"
        elif status == 404:
            not_found += 1
            if not_found >= 3:
                return 404, None
            reason = "404"
        elif status in (401, 403):
            token = None  # next pass fetches a fresh token
            reason = f"HTTP {status}, token discarded"
        else:
            reason = f"HTTP {status} {body[:200]!r}"
        failures += 1
        if failures > MAX_FAILURES:
            raise SystemExit(f"{path}: giving up after {failures} failures; last: {reason}")
        log(f"{path}: {reason}; retry {failures}")
        time.sleep(min(30, failures))


def is_orders_page(d):
    return isinstance(d, dict) and isinstance(d.get("items"), list) and {"page", "total_pages", "next"} <= d.keys()


def is_customer(d):
    return isinstance(d, dict) and {"id", "region", "discount_pct"} <= d.keys()


def fetch_orders():
    os.makedirs(PAGES_DIR, exist_ok=True)
    page, total_pages = 1, None
    while True:
        cache = os.path.join(PAGES_DIR, f"page-{page:03d}.json")
        if os.path.exists(cache):
            with open(cache) as f:
                data = json.load(f)
        else:
            status, data = call(f"/orders?page={page}", is_orders_page)
            if status != 200:
                raise SystemExit(f"/orders?page={page} returned {status}")
            if data["page"] != page:
                raise SystemExit(f"asked for page {page}, server returned page {data['page']}")
            with open(cache, "w") as f:
                json.dump(data, f)
            log(f"page {page}: {len(data['items'])} items, total_pages={data['total_pages']}, next={data['next']}")
        if total_pages is None:
            total_pages = data["total_pages"]
        if data["total_pages"] != total_pages:
            raise SystemExit(f"total_pages changed from {total_pages} to {data['total_pages']} at page {page}")
        expected_next = f"/orders?page={page + 1}" if page < total_pages else None
        if data["next"] != expected_next:
            raise SystemExit(f"page {page}: next={data['next']!r}, expected {expected_next!r}")
        if data["next"] is None:
            break
        page += 1
    log(f"fetched {page} pages (total_pages={total_pages})")


def load_listings():
    """Every order listing from the cached pages, in page order."""
    listings = []
    for name in sorted(os.listdir(PAGES_DIR)):
        with open(os.path.join(PAGES_DIR, name)) as f:
            listings.extend(json.load(f)["items"])
    return listings


def unique_orders(listings):
    """First listing per order id, plus the count of repeated listings and any repeats that differ."""
    by_id, dupes, conflicts = {}, 0, []
    for o in listings:
        seen = by_id.get(o["id"])
        if seen is None:
            by_id[o["id"]] = o
        else:
            dupes += 1
            if seen != o:
                conflicts.append((seen, o))
    return by_id, dupes, conflicts


def parse_utc(ts):
    if ts.endswith("Z"):  # normalise rather than rely on the Python version's fromisoformat
        ts = ts[:-1] + "+00:00"
    dt = datetime.fromisoformat(ts)
    if dt.tzinfo is None:
        raise SystemExit(f"placed_at has no offset: {ts!r}")
    return dt.astimezone(timezone.utc)


def qualifying(by_id):
    out = []
    for o in by_id.values():
        if o["status"] != "shipped":
            continue
        if RANGE_START <= parse_utc(o["placed_at"]) < RANGE_END:
            out.append(o)
    return out


def fetch_customers(qual):
    cache = {}
    if os.path.exists(CUSTOMERS_PATH):
        with open(CUSTOMERS_PATH) as f:
            cache = json.load(f)
    ids = sorted({o["customer_id"] for o in qual})
    fetched = 0
    for cid in ids:
        if cid in cache:
            continue
        status, data = call(f"/customers/{cid}", is_customer)
        cache[cid] = data if status == 200 else {"http_status": status}
        with open(CUSTOMERS_PATH, "w") as f:
            json.dump(cache, f, indent=1)
        fetched += 1
        if status != 200:
            log(f"customer {cid}: HTTP {status}")
    log(f"customers: {len(ids)} needed, {fetched} fetched this run, {len(cache)} cached")


def discounted_cents(amount, pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent for this order."""
    exact = Decimal(amount) * (100 - pct) / 100
    rounded = int(exact.quantize(Decimal(1), rounding=ROUND_HALF_UP))
    # integer cross-check; both agree for non-negative amounts, which compute() enforces
    assert rounded == (amount * (100 - pct) + 50) // 100, (amount, pct)
    return rounded


def compute():
    listings = load_listings()
    by_id, dupes, conflicts = unique_orders(listings)
    print(f"listings={len(listings)} distinct_ids={len(by_id)} repeated_listings={dupes} conflicting_repeats={len(conflicts)}")
    if conflicts:
        raise SystemExit(f"{len(conflicts)} repeated order ids differ in content; decide before computing")

    statuses = Counter(o["status"] for o in by_id.values())
    print("statuses:", dict(statuses))
    offsets = Counter(
        "Z" if o["placed_at"].endswith("Z") else o["placed_at"][-6:] for o in by_id.values()
    )
    print("placed_at offset forms:", dict(offsets))
    for o in by_id.values():
        parse_utc(o["placed_at"])  # fails loudly on any timestamp with no offset

    qual = qualifying(by_id)
    print(f"qualifying orders: {len(qual)}")

    with open(CUSTOMERS_PATH) as f:
        customers = json.load(f)
    by_region = {r: 0 for r in REGIONS}
    total = 0
    for o in qual:
        cid = o["customer_id"]
        c = customers.get(cid)
        if c is None or c.get("id") != cid or c.get("region") not in REGIONS:
            raise SystemExit(f"order {o['id']}: no usable customer record for {cid}: {c}")
        pct, amt = c["discount_pct"], o["amount_cents"]
        if not (isinstance(pct, int) and not isinstance(pct, bool) and 0 <= pct <= 100):
            raise SystemExit(f"customer {cid}: unusable discount_pct {pct!r}")
        if not (isinstance(amt, int) and not isinstance(amt, bool) and amt >= 0):
            raise SystemExit(f"order {o['id']}: unusable amount_cents {amt!r}")
        cents = discounted_cents(amt, pct)
        by_region[c["region"]] += cents
        total += cents

    assert sum(by_region.values()) == total
    assert len({o["id"] for o in qual}) == len(qual)
    result = {
        "total_cents": total,
        "order_count": len(qual),
        "duplicates_skipped": dupes,
        "by_region": by_region,
    }
    with open(RESULT_PATH, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    print(json.dumps(result, indent=2))


def main(cmd):
    os.makedirs(DATA_DIR, exist_ok=True)
    if cmd in ("orders", "all"):
        fetch_orders()
    if cmd in ("customers", "all"):
        by_id, _, _ = unique_orders(load_listings())
        fetch_customers(qualifying(by_id))
    if cmd in ("compute", "all"):
        compute()


if __name__ == "__main__":
    import sys

    main(sys.argv[1] if len(sys.argv) > 1 else "all")

